import math
class Solution:
    def findGreatestCommonDivisorOfArray(self, nums: list) -> int:
        result = nums[0]
        for value in nums[1:]:
            result = math.gcd(result, value)
        return result

import math
class Solution:
    def findGreatestCommonDivisorOfArray(self, nums: list) -> int:
        return math.gcd(nums[0], nums[-1])

class Solution:
    def findGreatestCommonDivisorOfArray(self, nums: list) -> int:
        return min(nums)

import math
class Solution:
    def findGreatestCommonDivisorOfArray(self, nums: list) -> int:
        low, high = min(nums), max(nums)
        return low * high // math.gcd(low, high)

import math
class Solution:
    def findGreatestCommonDivisorOfArray(self, nums: list) -> int:
        ordered = sorted(nums)
        return math.gcd(ordered[1], ordered[-1])

import math
class Solution:
    def findGreatestCommonDivisorOfArray(self, nums: list) -> int:
        return math.gcd(max(nums), max(nums))

class Solution:
    def findGreatestCommonDivisorOfArray(self, nums: list) -> int:
        return max(nums) - min(nums)

import math
class Solution:
    def findGreatestCommonDivisorOfArray(self, nums: list) -> int:
        return math.gcd(max(nums), min(nums))
